    function clampLat(lat) { return Math.min(Math.max(lat, g.lat0), g.lat0 + (g.nLat - 1) * g.latStep); }
    function clampLon(lon) { return Math.min(Math.max(lon, g.lon0), g.lon0 + (g.nLon - 1) * g.lonStep); }

    function sample(lat, lon) {
        var gx = (clampLon(lon) - g.lon0) / g.lonStep;
        var gy = (clampLat(lat) - g.lat0) / g.latStep;
        var x0 = Math.floor(gx), y0 = Math.floor(gy);
        var x1 = Math.min(x0 + 1, g.nLon - 1), y1 = Math.min(y0 + 1, g.nLat - 1);
        var fx = gx - x0, fy = gy - y0;
        function mix(v) {
            var a = v[y0 * g.nLon + x0], b = v[y0 * g.nLon + x1];
            var c = v[y1 * g.nLon + x0], d = v[y1 * g.nLon + x1];
            return (a * (1 - fx) + b * fx) * (1 - fy) + (c * (1 - fx) + d * fx) * fy;
        }
        return {e: mix(g.e), n: mix(g.n)};
    }

    window.LV03 = {
        // WGS84 lat/lng -> LV03 metres matching the swisstopo tiles
        project: function (lat, lon) {
            return sample(lat, lon);
        },
        // LV03 metres -> WGS84 lat/lng via Newton iteration on the grid
        unproject: function (eTarget, nTarget) {
            var lat = 46.95 + (nTarget - 200000) / 111300;
            var lon = 7.45 + (eTarget - 600000) / (111300 * Math.cos(lat * Math.PI / 180));
            var h = 0.001;
            for (var i = 0; i < 8; i++) {
                var p = sample(lat, lon);
                var de = p.e - eTarget, dn = p.n - nTarget;
                if (Math.abs(de) < 0.01 && Math.abs(dn) < 0.01) break;
                var pe = sample(lat, lon + h), pn = sample(lat + h, lon);
                var a = (pe.e - p.e) / h, b = (pn.e - p.e) / h;
                var c = (pe.n - p.n) / h, d = (pn.n - p.n) / h;
                var det = a * d - b * c;
                if (!isFinite(det) || det === 0) break;
                lon += (-de * d + dn * b) / det;
                lat += (-dn * a + de * c) / det;
            }
            return {lat: clampLat(lat), lng: clampLon(lon)};
        }
    };
